+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * imported sales against actual use (every consume movement). Only items
+ * where either is above zero; difference is actual minus theoretical.
+ */
+export function varianceReport(store, from, to) {
+  const round = (n) => Math.round(n * 1000) / 1000;
+  const theo = new Map();
+  const actual = new Map();
+  for (const sale of store.data.sales ?? []) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const line of sale.lines)
+      for (const u of line.uses) theo.set(u.itemId, (theo.get(u.itemId) ?? 0) + u.qty);
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  return [...new Set([...theo.keys(), ...actual.keys()])]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const t = round(theo.get(itemId) ?? 0);
+      const a = round(actual.get(itemId) ?? 0);
+      return { itemId, theoretical: t, actual: a, difference: round(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
