+// Sales from the till: each ticket consumes the recipe portions of the dishes
+// sold (ledger ref `sale:<ticket>`). A ticket is imported once.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** The imported sale for a ticket, or undefined. */
+export function findSale(store, ticket) {
+  return (store.data.sales ?? []).find((s) => s.ticket === ticket);
+}
+
+/**
+ * Books one ticket: `lines` are { dishId, qty }. Consumes the ingredients and
+ * keeps the theoretical use per line. Throws not_enough_stock when an item
+ * runs out (the caller rolls back, see src/io/sales-import.js).
+ */
+export function recordSale(store, { ticket, soldAt, lines }) {
+  const booked = lines.map((l, index) => {
+    const dish = getDish(store, l.dishId);
+    const uses = scaled(getRecipe(store, dish.recipeId), l.qty).filter((u) => u.qty > 0);
+    for (const u of uses) {
+      const item = getItem(store, u.itemId);
+      const available = onHand(store, u.itemId);
+      if (available < u.qty) throw new AppError("not_enough_stock", { item: item.name, available, unit: item.unit, line: index });
+      consume(store, u.itemId, u.qty, { at: soldAt, ref: `sale:${ticket}` });
+    }
+    return { dishId: l.dishId, qty: l.qty, uses };
+  });
+  store.data.sales ??= [];
+  const sale = { ticket, soldAt, lines: booked };
+  store.data.sales.push(sale);
+  return sale;
+}
